import functools

def cache(func):
    stored = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args not in stored:
            stored[args] = func(*args)
        return stored[args]
    return wrapper

@cache
def power(base, exp):
    """거듭제곱을 계산합니다."""
