import functools

def limit_calls(max_calls):
    def decorator(func):
        count = 0
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal count
            count += 1
            if count > max_calls:
                raise RuntimeError(f'{func.__name__}은 최대 {max_calls}번 호출 가능합니다.')
            return func(*args, **kwargs)
        _____
    return decorator

@limit_calls(max_calls=2)
def send_alert(msg):
    """경고 메시지를 전송합니다."""
    print(f'Alert: {msg}')

send_alert('disk full')
send_alert('memory low')
try:
    send_alert('cpu high')
except RuntimeError as e:
    print(e)
